/* ============================================================
   City Time Machine — styles
   Warm, cozy, miniature-world aesthetic.
   ============================================================ */

:root {
  --bg-deep: #1a1523;
  --bg-warm: #2a2135;
  --ink: #f5 ecd5;
  --ink: #f5ecd5;
  --ink-dim: #c8bfae;
  --accent: #ffb476;
  --accent-soft: #ffd9a8;
  --glass: rgba(40, 32, 52, 0.55);
  --glass-border: rgba(255, 210, 150, 0.22);
  --shadow: rgba(0, 0, 0, 0.45);
  --font-display: "Georgia", "Times New Roman", serif;
  --font-sans: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at 50% 30%, var(--bg-warm), var(--bg-deep) 80%);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

#scene-container {
  position: fixed;
  inset: 0;
  z-index: 0;
}

canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  touch-action: none;
}

/* ---------- Start overlay ---------- */
.start-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 40%, rgba(60, 45, 75, 0.9), rgba(20, 15, 30, 0.97) 80%);
  transition: opacity 0.9s ease, visibility 0.9s ease;
}
.start-overlay.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.start-card {
  text-align: center;
  padding: 48px 56px;
  border-radius: 24px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(10px);
  animation: floatIn 0.8s ease both;
}

@keyframes floatIn {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.title {
  font-family: var(--font-display);
  font-size: 44px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--accent-soft);
  text-shadow: 0 2px 20px rgba(255, 180, 118, 0.35);
  margin-bottom: 8px;
}

.subtitle {
  font-style: italic;
  color: var(--ink-dim);
  font-size: 16px;
  margin-bottom: 30px;
}

.enter-btn {
  font-family: var(--font-sans);
  font-size: 17px;
  font-weight: 600;
  color: #241a2c;
  background: linear-gradient(135deg, var(--accent), var(--accent-soft));
  border: none;
  border-radius: 999px;
  padding: 15px 34px;
  cursor: pointer;
  box-shadow: 0 10px 30px rgba(255, 180, 118, 0.35);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.enter-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 40px rgba(255, 180, 118, 0.5);
}
.enter-btn:active {
  transform: translateY(0);
}
.enter-btn__icon {
  font-size: 20px;
}

.hint {
  margin-top: 24px;
  font-size: 12px;
  letter-spacing: 0.6px;
  color: rgba(245, 236, 213, 0.5);
  text-transform: uppercase;
}

/* ---------- HUD ---------- */
.hud-top {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: none;
}
.brand__mark {
  font-size: 22px;
  color: var(--accent);
  filter: drop-shadow(0 0 10px rgba(255, 180, 118, 0.5));
}
.brand__name {
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.5px;
}

.clock {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  pointer-events: none;
}
.clock__day {
  font-family: var(--font-display);
  font-size: 15px;
  color: var(--accent-soft);
  letter-spacing: 1px;
}
.clock__time {
  font-variant-numeric: tabular-nums;
  font-size: 13px;
  color: var(--ink-dim);
}

/* ---------- Control panel ---------- */
.control-panel {
  position: fixed;
  bottom: 22px;
  left: 22px;
  z-index: 20;
  width: 240px;
  padding: 18px;
  border-radius: 18px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  box-shadow: 0 16px 40px var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(12px);
}

.control-group {
  margin-bottom: 16px;
}
.control-group:last-child {
  margin-bottom: 0;
}
.control-group > label {
  display: block;
  font-size: 10px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--ink-dim);
  margin-bottom: 8px;
}

.toggle-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  font-family: var(--font-sans);
  font-size: 14px;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 10px 14px;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}
.toggle-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}
.toggle-btn[aria-pressed="false"] {
  opacity: 0.55;
}
.toggle-btn__glyph {
  font-size: 16px;
  color: var(--accent);
}
.toggle-btn__label {
  margin-left: auto;
}

/* Time slider */
.time-slider {
  width: 100%;
}
#time-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 4px;
  background: linear-gradient(90deg, #ffe9b8, #ffb476 25%, #8a6fd6 55%, #2b2450 80%, #ffd9a8);
  outline: none;
  cursor: pointer;
}
#time-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--accent);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  cursor: pointer;
}
#time-range::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--accent);
  cursor: pointer;
}
.time-track {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 12px;
  opacity: 0.7;
}

.btn-row {
  display: flex;
  gap: 8px;
}
.mini-btn {
  flex: 1;
  font-family: var(--font-sans);
  font-size: 13px;
  color: var(--ink-dim);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--glass-border);
  border-radius: 9px;
  padding: 9px 0;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}
.mini-btn:hover {
  background: rgba(255, 180, 118, 0.18);
  color: var(--accent-soft);
}

/* ---------- Info card ---------- */
.info-card {
  position: fixed;
  bottom: 22px;
  right: 22px;
  z-index: 20;
  width: 230px;
  padding: 18px 20px;
  border-radius: 16px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  box-shadow: 0 16px 40px var(--shadow);
  backdrop-filter: blur(12px);
  transform: translateY(10px);
  opacity: 0;
  transition: opacity 0.35s ease, transform 0.35s ease;
  pointer-events: none;
}
.info-card.is-visible {
  transform: none;
  opacity: 1;
}
.info-card__title {
  font-family: var(--font-display);
  font-size: 19px;
  color: var(--accent-soft);
  margin-bottom: 6px;
}
.info-card__desc {
  font-size: 13px;
  line-height: 1.5;
  color: var(--ink-dim);
}

/* ---------- HUD bottom ---------- */
.hud-bottom {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 15;
  display: flex;
  gap: 12px;
  font-size: 11px;
  letter-spacing: 0.8px;
  color: rgba(245, 236, 213, 0.55);
  text-transform: uppercase;
  pointer-events: none;
}

/* Dim the HUD during interaction */
body.is-interacting .hud-bottom {
  opacity: 0;
}

@media (max-width: 640px) {
  .title {
    font-size: 32px;
  }
  .control-panel {
    width: 200px;
    left: 12px;
    bottom: 74px;
  }
  .hud-bottom {
    display: none;
  }
}

/* ============================================================
   City Time Machine — 3D diorama + lo-fi soundtrack
   ------------------------------------------------------------
   Sections:
     1. Imports & bootstrap
     2. Utility helpers (colors, noise, rng)
     3. Scene / camera / renderer setup
     4. Orbit controls (custom, no external addon dependency)
     5. The diorama world (ground, roads, buildings, props)
     6. Materials & emissive windows
     7. Lighting + day/night sky system
     8. Animated props (cars, people, clouds, steam)
     9. Raycasting / building info
     10. Web Audio lo-fi soundtrack engine
     11. UI wiring + clock
     12. Animation loop
   ============================================================ */

import * as THREE from "three";

/* ---------- 1. Bootstrap ---------- */

const container = document.getElementById("scene-container");
const startOverlay = document.getElementById("start-overlay");
const enterBtn = document.getElementById("enter-btn");

// Public state (exposed for debugging / self-test)
const AppState = {
  audioPlaying: false,
  orbitEnabled: true,
  timeOfDay: 0.65, // 0 = midnight, 0.5 = noon, 1 = midnight
  isStarted: false,
  selectedBuilding: null,
};
window.__cityTimeMachine = AppState;

// Core objects (filled in setup)
let scene, camera, renderer, controls;
let worldGroup;          // holds all diorama content, rotates for orbit
let skyDome, stars;
let sunLight, moonLight, ambientLight, hemiLight;
let emissiveWindows = []; // {mesh, baseIntensity, targetIntensity}
let animatedProps = [];   // {update(dt)}
let audioCtx = null;
let audioNodes = {};
const clock = new THREE.Clock();

/* ---------- 2. Utility helpers ---------- */

// Deterministic-ish random for varied but stable props
function rng(seed) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return () => (s = (s * 16807) % 2147483647) / 2147483647;
}

// Smooth interpolation helper
const lerp = (a, b, t) => a + (b - a) * t;

// Convert hex color to three color
function hex(h) {
  return new THREE.Color(h);
}

// Light warm/cool tone based on time of day (see 7)
function warmTint(t) {
  return new THREE.Color().setHSL(0.09, 0.7, 0.55 + t * 0.1);
}

/* ---------- 3. Scene / camera / renderer ---------- */

function setupRenderer() {
  renderer = new THREE.WebGLRenderer({
    antialias: true,
    powerPreference: "high-performance",
  });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);
}

function setupScene() {
  scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x2a2135, 0.012);

  camera = new THREE.PerspectiveCamera(
    45,
    window.innerWidth / window.innerHeight,
    0.1,
    500
  );
  camera.position.set(22, 18, 26);

  worldGroup = new THREE.Group();
  scene.add(worldGroup);
}

/* ---------- 4. Orbit controls (custom) ---------- */
// Lightweight orbit + zoom with damping. See orbitControls.js logic inline.

function initControls() {
  controls = new OrbitController(camera, renderer.domElement);
  controls.target.set(0, 2, 0);
  controls.minDistance = 8;
  controls.maxDistance = 60;
  controls.maxPolarAngle = Math.PI * 0.49; // don't go below ground
  controls.enableDamping = true;
  controls.damping = 0.08;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 0.6;
}

/* ---------- 5. Build the world ---------- */

function buildWorld() {
  buildGround();
  buildRoads();
  buildBlockBase();
  buildBuildings();
  buildStorefronts();
  buildProps();
  buildTrees();
  buildStreetLights();
  buildCars();
  buildPeople();
  buildClouds();
  buildSteam();
}

function buildGround() {
  // Soft grassy base platform (the diorama "ground")
  const geo = new THREE.CircleGeometry(40, 96);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x3a5a3a,
    roughness: 0.95,
    metalness: 0.0,
  });
  const ground = new THREE.Mesh(geo, mat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  worldGroup.add(ground);
}

function buildBlockBase() {
  // Raised platform edge so it reads as a "miniature diorama"
  const baseGeo = new THREE.CylinderGeometry(38, 39, 2, 96);
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x4a3f52, roughness: 0.9 });
  const base = new THREE.Mesh(baseGeo, baseMat);
  base.position.y = -1;
  base.receiveShadow = true;
  base.castShadow = true;
  worldGroup.add(base);
}

function buildRoads() {
  // A simple grid of roads cutting through the block
  const roadMat = new THREE.MeshStandardMaterial({ color: 0x2b2b30, roughness: 0.85 });
  const laneMat = new THREE.MeshBasicMaterial({ color: 0xd8d2a0 });

  const road = (x, z, w, d) => {
    const g = new THREE.BoxGeometry(w, 0.05, d);
    const m = new THREE.Mesh(g, roadMat);
    m.position.set(x, 0.02, z);
    m.receiveShadow = true;
    worldGroup.add(m);
  };
  // Horizontal and vertical roads forming a grid
  road(0, 0, 80, 6);
  road(0, 0, 6, 80);
  road(16, 12, 30, 6);
  road(12, 16, 6, 30);
}

/* ---------- 6. Materials & emissive windows ---------- */
// Filled in next.

/* ---------- 7. Lighting ---------- */
// Filled in next.

/* ---------- 8. Animated props ---------- */
// Filled in next.

/* ---------- 9. Raycasting ---------- */
// Filled in next.

/* ---------- 10. Web Audio lo-fi soundtrack ---------- */
// Filled in next.

/* ---------- 11. UI wiring ---------- */
// Filled in next.

/* ---------- 12. Animation loop ---------- */
// Filled in next.

/* ---------- OrbitController class ---------- */
// A self-contained orbit control implementation.

class OrbitController {
  constructor(camera, domElement) {
    this.camera = camera;
    this.domElement = domElement;
    this.target = new THREE.Vector3();
    this.minDistance = 8;
    this.maxDistance = 60;
    this.minPolarAngle = 0.1;
    this.maxPolarAngle = Math.PI * 0.49;
    this.enableDamping = true;
    this.damping = 0.1;
    this.autoRotate = false;
    this.autoRotateSpeed = 1.0;
    this.rotateSpeed = 0.0025;
    this.zoomSpeed = 1.1;

    // Spherical coordinates
    this.spherical = new THREE.Spherical();
    this.sphericalTarget = new THREE.Spherical();
    this._initSpherical();
    this._cloneTarget = this.target.clone();

    this._bindEvents();
  }

  _initSpherical() {
    const offset = this.camera.position.clone().sub(this.target);
    this.spherical.setFromVector3(offset);
    this.sphericalTarget.copy(this.spherical);
  }

  _bindEvents() {
    this._onDown = null;
    this._lastX = 0;
    this._lastY = 0;

    this.domElement.addEventListener("mousedown", (e) => this._onMouseDown(e));
    this.domElement.addEventListener("mousemove", (e) => this._onMouseMove(e));
    window.addEventListener("mouseup", () => this._onMouseUp());
    this.domElement.addEventListener("wheel", (e) => this._onWheel(e), { passive: false });
    this.domElement.addEventListener("contextmenu", (e) => e.preventDefault());

    // Touch
    this.domElement.addEventListener("touchstart", (e) => this._onTouchStart(e), { passive: false });
    this.domElement.addEventListener("touchmove", (e) => this._onTouchMove(e), { passive: false });
    this.domElement.addEventListener("touchend", () => this._onTouchEnd());

    this._dragging = false;
  }

  _onMouseDown(e) {
    this._dragging = true;
    this._lastX = e.clientX;
    this._lastY = e.clientY;
    document.body.classList.add("is-interacting");
  }
  _onMouseUp() {
    this._dragging = false;
    document.body.classList.remove("is-interacting");
  }
  _onMouseMove(e) {
    if (!this._dragging) return;
    const dx = e.clientX - this._lastX;
    const dy = e.clientY - this._lastY;
    this._lastX = e.clientX;
    this._lastY = e.clientY;
    this.sphericalTarget.theta -= dx * this.rotateSpeed;
    this.sphericalTarget.phi -= dy * this.rotateSpeed;
    this._clamp();
  }
  _onWheel(e) {
    e.preventDefault();
    if (e.deltaY > 0) this.sphericalTarget.radius *= this.zoomSpeed;
    else this.sphericalTarget.radius /= this.zoomSpeed;
    this._clamp();
  }

  _onTouchStart(e) {
    if (e.touches.length === 1) {
      this._dragging = true;
      this._lastX = e.touches[0].clientX;
      this._lastY = e.touches[0].clientY;
    } else if (e.touches.length === 2) {
      this._pinchDist = this._touchDist(e.touches);
      this._dragging = true;
    }
    document.body.classList.add("is-interacting");
  }
  _onTouchMove(e) {
    e.preventDefault();
    if (e.touches.length === 1 && this._dragging) {
      const dx = e.touches[0].clientX - this._lastX;
      const dy = e.touches[0].clientY - this._lastY;
      this._lastX = e.touches[0].clientX;
      this._lastY = e.touches[0].clientY;
      this.sphericalTarget.theta -= dx * this.rotateSpeed;
      this.sphericalTarget.phi -= dy * this.rotateSpeed;
      this._clamp();
    } else if (e.touches.length === 2) {
      const d = this._touchDist(e.touches);
      if (this._pinchDist) {
        const r = this.sphericalTarget.radius;
        if (d > this._pinchDist) r *= this.zoomSpeed;
        else r /= this.zoomSpeed;
        this.sphericalTarget.radius = Math.max(this.minDistance, Math.min(this.maxDistance, r));
      }
      this._pinchDist = d;
    }
  }
  _onTouchEnd() {
    this._dragging = false;
    document.body.classList.remove("is-interacting");
  }
  _touchDist(touches) {
    const dx = touches[0].clientX - touches[1].clientX;
    const dy = touches[0].clientY - touches[1].clientY;
    return Math.sqrt(dx * dx + dy * dy);
  }

  _clamp() {
    this.sphericalTarget.phi = Math.max(
      this.minPolarAngle,
      Math.min(this.maxPolarAngle, this.sphericalTarget.phi)
    );
    this.sphericalTarget.radius = Math.max(
      this.minDistance,
      Math.min(this.maxDistance, this.sphericalTarget.radius)
    );
  }

  update() {
    if (this.autoRotate) {
      this.sphericalTarget.theta += 0.001 * this.autoRotateSpeed;
    }
    // Damping
    this.spherical.theta += (this.sphericalTarget.theta - this.spherical.theta) * this.damping;
    this.spherical.phi += (this.sphericalTarget.phi - this.spherical.phi) * this.damping;
    this.spherical.radius += (this.sphericalTarget.radius - this.spherical.radius) * this.damping;

    const offset = new THREE.Spherical().copy(this.spherical);
    this.camera.position.copy(this.target).add(new THREE.Vector3().setFromSpherical(offset));
    this.camera.lookAt(this.target);
  }

  dispose() {
    // listeners are on window/dom; kept simple for this app
  }
}

/* ---------- Start / run ---------- */

function startApp() {
  if (AppState.isStarted) return;
  AppState.isStarted = true;
  startOverlay.classList.add("is-hidden");

  setupRenderer();
  setupScene();
  initControls();
  buildWorld();
  setupLighting();
  buildSky();
  initAudio();
  wireUI();
  window.addEventListener("resize", onResize);
  animate();
}

function onResize() {
  if (!camera || !renderer) return;
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  if (controls) controls.update();

  // Update animated props
  for (const prop of animatedProps) {
    if (typeof prop.update === "function") prop.update(dt, t);
  }

  // Update day/night based on time-of-day target
  updateDayNight(AppState.timeOfDay);

  renderer.render(scene, camera);
}

/* Wire the enter button */
enterBtn.addEventListener("click", () => {
  startApp();
});

// Kick off rendering pipeline only after user gesture (audio requirement)
// Nothing else runs until startApp().

