+  if (Math.random() < 0.5) {
+    const degree = Math.floor(Math.random() * SCALE.length);
+    const oct = Math.random() < 0.5 ? 0 : 12;
+    const m = 72 + SCALE[degree] + oct; // around A4
+    playNote(m, "sine", 0.05, now, 0.5, 0.6);
