// Build a single cozy shop with body, roof, windows, door, sign
function createShop(b, facadeColor, info) {
  const group = new THREE.Group();
  group.position.set(b.x, 0, b.z);

  const floors = b.floors;
  const floorH = 2.0;
  const height = floors * floorH;
