function startApp() {
  if (AppState.isStarted) return;
  AppState.isStarted = true;
  startOverlay.classList.add("is-hidden");

  setupRenderer();
  setupScene();
  initControls();
  buildWorld();
  setupLighting();
  buildSky();
  initAudio();
  wireUI();
  window.addEventListener("resize", onResize);
  animate();
}

